"""Private object storage for uploaded originals.

Access control:

* The bucket is private (``init-storage`` blocks public access); no URL to an object is ever
  handed to a browser. Files leave storage only through the API, after authorization.
* Keys are generated by the server from UUIDs (``orgs/{org}/chatbots/{bot}/documents/{doc}/...``);
  user-supplied filenames never become part of a key, so path tricks are impossible.
* Callers check ``key_belongs_to_org`` before reading or deleting, so a bug that passes another
  tenant's key fails closed instead of returning their file.
"""

from __future__ import annotations

import contextlib
import threading
import uuid
from typing import TYPE_CHECKING, Protocol

import boto3
from botocore.config import Config
from botocore.exceptions import BotoCoreError, ClientError

if TYPE_CHECKING:
    from app.core.config import Settings


class StorageError(Exception):
    """Storage was unreachable or refused the request (transient from the job's viewpoint)."""


class ObjectNotFoundError(StorageError):
    pass


class ObjectStore(Protocol):
    def put(self, key: str, data: bytes, *, content_type: str) -> None: ...
    def get(self, key: str, *, max_bytes: int) -> bytes: ...
    def delete(self, key: str) -> None: ...
    def ensure_ready(self) -> None: ...


def document_key(
    org_id: uuid.UUID, chatbot_id: uuid.UUID, document_id: uuid.UUID, version: int
) -> str:
    return f"orgs/{org_id}/chatbots/{chatbot_id}/documents/{document_id}/v{version}/original"


def key_belongs_to_org(key: str, org_id: uuid.UUID) -> bool:
    return key.startswith(f"orgs/{org_id}/") and ".." not in key


class S3ObjectStore:
    def __init__(self, settings: Settings) -> None:
        access = settings.s3_access_key.get_secret_value() if settings.s3_access_key else None
        secret = settings.s3_secret_key.get_secret_value() if settings.s3_secret_key else None
        self._bucket = settings.s3_bucket
        self._client = boto3.client(
            "s3",
            endpoint_url=settings.s3_endpoint_url,
            region_name=settings.s3_region,
            aws_access_key_id=access,
            aws_secret_access_key=secret,
            config=Config(
                signature_version="s3v4",
                s3={"addressing_style": "path"},
                connect_timeout=5,
                read_timeout=30,
                retries={"max_attempts": 2, "mode": "standard"},
            ),
        )

    def put(self, key: str, data: bytes, *, content_type: str) -> None:
        try:
            self._client.put_object(
                Bucket=self._bucket, Key=key, Body=data, ContentType=content_type
            )
        except (BotoCoreError, ClientError) as exc:
            msg = f"put failed: {type(exc).__name__}"
            raise StorageError(msg) from exc

    def get(self, key: str, *, max_bytes: int) -> bytes:
        try:
            response = self._client.get_object(Bucket=self._bucket, Key=key)
            if response.get("ContentLength", 0) > max_bytes:
                msg = "object is larger than allowed"
                raise StorageError(msg)
            data: bytes = response["Body"].read(max_bytes + 1)
        except ClientError as exc:
            if exc.response.get("Error", {}).get("Code") in {"NoSuchKey", "404"}:
                msg = "object not found"
                raise ObjectNotFoundError(msg) from exc
            msg = f"get failed: {type(exc).__name__}"
            raise StorageError(msg) from exc
        except BotoCoreError as exc:
            msg = f"get failed: {type(exc).__name__}"
            raise StorageError(msg) from exc
        if len(data) > max_bytes:
            msg = "object is larger than allowed"
            raise StorageError(msg)
        return data

    def delete(self, key: str) -> None:
        try:
            self._client.delete_object(Bucket=self._bucket, Key=key)
        except (BotoCoreError, ClientError) as exc:
            msg = f"delete failed: {type(exc).__name__}"
            raise StorageError(msg) from exc

    def ensure_ready(self) -> None:
        """Create the bucket if needed and block all public access (idempotent)."""
        try:
            try:
                self._client.head_bucket(Bucket=self._bucket)
            except ClientError:
                self._client.create_bucket(Bucket=self._bucket)
            with contextlib.suppress(ClientError):
                self._client.put_public_access_block(
                    Bucket=self._bucket,
                    PublicAccessBlockConfiguration={
                        "BlockPublicAcls": True,
                        "IgnorePublicAcls": True,
                        "BlockPublicPolicy": True,
                        "RestrictPublicBuckets": True,
                    },
                )
        except (BotoCoreError, ClientError) as exc:
            msg = f"bucket setup failed: {type(exc).__name__}"
            raise StorageError(msg) from exc


class MemoryObjectStore:
    """In-process store for tests and local experiments; never selected in production."""

    def __init__(self) -> None:
        self._objects: dict[str, bytes] = {}
        self._lock = threading.Lock()
        self.fail_next_put = 0
        self.fail_next_get = 0

    def put(self, key: str, data: bytes, *, content_type: str) -> None:
        if self.fail_next_put:
            self.fail_next_put -= 1
            msg = "simulated put failure"
            raise StorageError(msg)
        with self._lock:
            self._objects[key] = bytes(data)

    def get(self, key: str, *, max_bytes: int) -> bytes:
        if self.fail_next_get:
            self.fail_next_get -= 1
            msg = "simulated get failure"
            raise StorageError(msg)
        with self._lock:
            data = self._objects.get(key)
        if data is None:
            msg = "object not found"
            raise ObjectNotFoundError(msg)
        if len(data) > max_bytes:
            msg = "object is larger than allowed"
            raise StorageError(msg)
        return data

    def delete(self, key: str) -> None:
        with self._lock:
            self._objects.pop(key, None)

    def ensure_ready(self) -> None:
        return None

    def keys(self) -> list[str]:
        with self._lock:
            return sorted(self._objects)


def build_object_store(settings: Settings) -> ObjectStore:
    if settings.storage_backend == "memory":
        return MemoryObjectStore()
    return S3ObjectStore(settings)
